(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库')?.click();
  await sleep(2400);
  const box = document.querySelector('.lib-intro');
  return JSON.stringify({
    cards: document.querySelectorAll('.lib-card').length,
    introShown: !!box,
    introTitle: box?.querySelector('h2')?.textContent || null,
    introParas: box ? [...box.querySelectorAll('p')].map((p) => p.textContent.trim().slice(0, 40)) : [],
    introItems: box ? [...box.querySelectorAll('li')].map((li) => li.textContent.trim().slice(0, 30)) : [],
    strongWords: box ? [...box.querySelectorAll('strong')].map((s) => s.textContent.trim()) : [],
    addButtonStillThere: !!document.querySelector('.lib-add'),
    introAboveGrid: box && document.querySelector('.lib-grid') ? (box.compareDocumentPosition(document.querySelector('.lib-grid')) & Node.DOCUMENT_POSITION_FOLLOWING) > 0 : null,
  });
})()
